import React, { useCallback, useMemo, useRef, useState } from 'react';
import {
  SearchInput,
  ParcelComponent,
  createParcelCreateFooterRenderer,
  isParcelRuntimeAvailable,
  type ParcelLinkConfig,
} from '@linm-soft-org/linm-web-common-components';
import type { CustomerDto } from '../../services/kt/models';
import df from '../../styles/documentForm.module.css';
import { formatAccountDisplay } from './accountSearchApi';
import {
  createCustomerSearchConfig,
  type CreateCustomerSearchConfigOptions,
  type CustomerSearchType,
} from './customerSearchConfig';
import {
  CUSTOMER_CREATE_PARCEL,
  mapCustomerCreateResultToDto,
  type CustomerCreateParcelCustomProps,
  type CustomerCreatePrefill,
} from './searchParcelConfig';

export type { CustomerCreatePrefill };

export type CustomerSearchFieldProps = {
  customerId: string;
  customerCode: string;
  customerName: string;
  onSelect: (customer: CustomerDto) => void;
  onClear: () => void;
  disabled?: boolean;
  placeholder?: string;
  className?: string;
  error?: string;
  /** Parcel link — default `CUSTOMER_CREATE_PARCEL`; `false` = no create footer */
  createParcel?: ParcelLinkConfig | false;
  /** Prefill form parcel khi bấm Tạo mới. */
  createPrefill?: CustomerCreatePrefill;
  searchConfigOptions?: CreateCustomerSearchConfigOptions;
  defaultCustomerType?: CustomerSearchType;
  testIdPrefix?: string;
  /** Một ô `mã — tên`. Mặc định: false — 2 ô mã + tên cùng hàng. */
  singleField?: boolean;
};

/**
 * SearchControl consumer — SearchInput + ParcelComponent (`search-parcel.md`).
 * Sau Lưu parcel → `onSelect(CustomerDto)` để map chứng từ / hiển thị SearchInput.
 * Cancel / đóng parcel → reset draft term trên SearchInput.
 */
export function CustomerSearchField({
  customerId,
  customerCode,
  customerName,
  onSelect,
  onClear,
  disabled = false,
  placeholder,
  className,
  error,
  createParcel = CUSTOMER_CREATE_PARCEL,
  createPrefill,
  searchConfigOptions,
  defaultCustomerType = 'Customer',
  testIdPrefix = 'customer-search',
  singleField = false,
}: CustomerSearchFieldProps): React.ReactElement {
  const tid = (suffix: string) => `${testIdPrefix}-${suffix}`;
  const searchConfig = useMemo(
    () => createCustomerSearchConfig(searchConfigOptions ?? {}),
    [searchConfigOptions],
  );

  const [parcelOpen, setParcelOpen] = useState(false);
  const [initialName, setInitialName] = useState('');
  const [initialBankAccountNumber, setInitialBankAccountNumber] = useState('');
  const [initialBankName, setInitialBankName] = useState('');
  const [draftResetToken, setDraftResetToken] = useState(0);

  const onSelectRef = useRef(onSelect);
  onSelectRef.current = onSelect;
  const defaultCustomerTypeRef = useRef(defaultCustomerType);
  defaultCustomerTypeRef.current = defaultCustomerType;

  const parcelLink = createParcel === false ? null : (createParcel ?? CUSTOMER_CREATE_PARCEL);
  const canCreate = !!parcelLink && !disabled && isParcelRuntimeAvailable();

  const resetSearchDraft = useCallback(() => {
    setDraftResetToken(t => t + 1);
  }, []);

  const closeParcel = useCallback(() => {
    setParcelOpen(false);
    resetSearchDraft();
  }, [resetSearchDraft]);

  const parcelCustomProps = useMemo((): CustomerCreateParcelCustomProps => ({
    initialName,
    initialBankAccountNumber: initialBankAccountNumber || undefined,
    initialBankName: initialBankName || undefined,
    defaultCustomerType,
    onSuccess: created => {
      onSelectRef.current(
        mapCustomerCreateResultToDto(created, defaultCustomerTypeRef.current),
      );
      setParcelOpen(false);
      resetSearchDraft();
    },
    onCancel: closeParcel,
  }), [
    initialName,
    initialBankAccountNumber,
    initialBankName,
    defaultCustomerType,
    resetSearchDraft,
    closeParcel,
  ]);

  const renderCreateFooter = useMemo(() => {
    if (!canCreate || !parcelLink) return undefined;
    return createParcelCreateFooterRenderer({
      link: parcelLink,
      testId: tid('create-btn'),
      defaultLabel: 'Tạo mới đối tượng',
      onOpen: term => {
        const prefillName = createPrefill?.name?.trim();
        setInitialName(prefillName || term || '');
        setInitialBankAccountNumber(createPrefill?.bankAccountNumber?.trim() || '');
        setInitialBankName(createPrefill?.bankName?.trim() || '');
        setParcelOpen(true);
      },
    });
  }, [canCreate, parcelLink, testIdPrefix, createPrefill]);

  const rootClassName = [
    className,
    !singleField ? df.customerLookupDualRow : undefined,
  ]
    .filter(Boolean)
    .join(' ');

  return (
    <>
      <SearchInput
        key={draftResetToken}
        config={searchConfig}
        className={rootClassName || undefined}
        value={customerId}
        primaryDisplay={
          singleField
            ? formatAccountDisplay(customerCode, customerName)
            : customerCode
        }
        secondaryDisplay={singleField ? '' : customerName}
        onChange={onSelect}
        onClear={onClear}
        showLabel={false}
        showSecondaryInput={!singleField}
        placeholder={placeholder}
        disabled={disabled}
        error={error}
        renderDropdownFooter={renderCreateFooter}
      />

      {parcelLink ? (
        <ParcelComponent
          isOpen={parcelOpen}
          link={parcelLink}
          customProps={parcelCustomProps}
          onClose={closeParcel}
          testIdPrefix={tid('parcel')}
        />
      ) : null}
    </>
  );
}
